static uint8_t prop_knob(void *u, uint8_t f, bhms_value *o, bhms_sample *m) {
    arm_device *d = self(u);
    o->f = d->a->sv[ARM_S_KNOB].pos_deg;
    if (d->a->tool_id != ARM_TOOL_KNOB_TURNER || d->a->tool_state != TOOL_ST_READY)
        return BHMS_Q_UNKNOWN;
    return servo_sample(d, &d->a->sv[ARM_S_KNOB], f, m);
}
