/* ---- Stop and completion sink ------------------------------------------------------------- */
static uint8_t dev_stop(void *u, uint8_t reason, uint8_t *evidence) {
    arm_device *d = self(u);
    uint8_t measured = 0;
    arm_stop_result r;
    (void)reason;
    r = arm_stop(d->a, &measured);
    d->op_handle = 0; /* the endpoint cancels every active operation itself */
    *evidence = measured ? BHMS_EV_MEASURED : BHMS_EV_REPORTED;
    return r == ARM_STOP_CONFIRMED ? BHMS_STOPACK_CONFIRMED : BHMS_STOPACK_INITIATED;
}

static void sink_stop_confirmed(void *ctx, uint8_t measured) {
    bhms_stop_confirmed(&self(ctx)->ep, measured ? BHMS_EV_MEASURED : BHMS_EV_REPORTED);
}

static void sink_progress(void *ctx, uint8_t percent) {
    arm_device *d = self(ctx);
    if (d->op_handle != 0) (void)bhms_op_progress(&d->ep, d->op_handle, percent);
}

static void sink_finished(void *ctx, const arm_completion *done) {
    arm_device *d = self(ctx);
    bhms_value r[BHMS_MAX_FIELDS];
    uint16_t handle = d->op_handle;
    uint8_t state, evidence = done->measured ? BHMS_EV_MEASURED : BHMS_EV_REPORTED;
    memset(r, 0, sizeof r);
    if (handle == 0) return;
    d->op_handle = 0;
    switch (done->kind) {
    case ARM_OP_MOVE:
    case ARM_OP_HOME:
    case ARM_OP_RELEASE:
        r[0].u = clamp_u32(done->values[0] * 100.0f, 65535.0f);
        break;
    case ARM_OP_TOOL_MOUNT:
        r[0].u = clamp_u32(done->values[0], 255.0f);
        break;
    case ARM_OP_GRIP:
        r[0].u = clamp_u32(done->values[0] * 10.0f, 65535.0f);
        r[1].u = done->values[1] > 0.5f ? 1u : 0u;
        break;
    case ARM_OP_TURN:
        r[0].i = (int32_t)lroundf(done->values[0] * 10.0f);
        r[1].u = done->values[1] > 0.5f ? 1u : 0u;
        break;
    case ARM_OP_PRESS:
        r[0].u = clamp_u32(done->values[0], 100.0f);
        r[1].u = clamp_u32(done->values[1] * 10.0f, 255.0f);
        break;
    default:
        break;
    }
    state = done->status == ARM_DONE_COMPLETED ? BHMS_ST_COMPLETED
            : done->status == ARM_DONE_CANCELED ? BHMS_ST_CANCELED : BHMS_ST_FAILED;
    (void)bhms_op_finish(&d->ep, handle, state, evidence, done->fault, r);
}

/* ---- Lifecycle ------------------------------------------------------------------------------ */
bhms_err arm_device_init(arm_device *d, arm *a, const bhms_hal *hal) {
    static const uint8_t kDigest[8] = BHMS_DIGEST8;
    memset(d, 0, sizeof *d);
    d->a = a;
    memcpy(d->dev.digest8, kDigest, sizeof kDigest);
    d->dev.flags = BHMS_DEV_FENCING;
    d->dev.actions = kActions;
    d->dev.n_actions = ARM_ACT_COUNT;
    d->dev.properties = kProps;
    d->dev.n_properties = ARM_PROP_COUNT;
    d->dev.stop = dev_stop;
    d->dev.user = d;
    d->sink.ctx = d;
    d->sink.finished = sink_finished;
    d->sink.progress = sink_progress;
    d->sink.stop_confirmed = sink_stop_confirmed;
    a->sink = &d->sink;
    return bhms_init(&d->ep, &d->dev, hal);
}

void arm_device_poll(arm_device *d) {
    bhms_poll(&d->ep);
    arm_tick(d->a);
}

const bhms_device *arm_device_table(const arm_device *d) { return &d->dev; }
